CREATE POLICY "Creators record own agreement" ON public.legal_consents FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'creator'::public.app_role) AND consent_type = 'creator_agreement' AND length(consent_text) BETWEEN 1 AND 5000 AND length(terms_version) BETWEEN 1 AND 20 AND (email IS NULL OR length(email) <= 320) AND (username IS NULL OR length(username) <= 100) AND (ip_address IS NULL OR length(ip_address) <= 64) AND (user_agent IS NULL OR length(user_agent) <= 1000));